Las consultas se realizan sobre el punto <a href="http://www.zaragoza.es/ciudad/risp/sparql.htm">SPARQL</a> y el <strong>grafo: http://www.zaragoza.es/sector-publico/contrato</strong><br/>
Ejemplo:
<h4>Lista de contratos por servicio gestor</h4>
<pre xml:space="preserve">PREFIX pproc: &lt;http://contsem.unizar.es/def/sector-publico/pproc#&gt;
PREFIX dcterms: &lt;http://purl.org/dc/terms/&gt;

SELECT DISTINCT ?uriCont ?title WHERE {?uriCont a &lt;http://contsem.unizar.es/def/sector-publico/pproc#Contract&gt;;
pproc:managingDepartment ?managingDepartment.
?managingDepartment dcterms:title ?title} ORDER BY ?title</pre>

Las consultas se realizan sobre el punto <a href="http://www.zaragoza.es/ciudad/risp/sparql.htm">SPARQL</a> y el <strong>grafo: http://www.zaragoza.es/medio-ambiente/calidad-aire/</strong>
<h4>Obtener contaminante, estacion, fecha,valor medicion horaria, y verficacion para una estacion y fecha concreta</h4>
<pre xml:space="preserve">PREFIX ssn:&lt;http://purl.oclc.org/NET/ssnx/ssn#&gt;
PREFIX ssnext:&lt;http://vocab.linkeddata.es/datosabiertos/def/medio-ambiente/calidad-aire/ssn-ext#&gt;
PREFIX dul:&lt;http://www.loa-cnr.it/ontologies/DUL.owl#&gt;
select distinct ?magnitud ?estacion ?fecha ?valor ?verif

where {
        ?uri a ssn:Observation;
        ssn:observedBy ?estacion;
        ssn:observationResult ?res;
        ssn:observedProperty ?magnitud;
        ssnext:observationStatus ?verif;
        ssn:observationResultTime ?fecha.
        ?res ssn:hasValue/dul:hasDataValue ?valor
  filter  (?fecha&gt;"2015-02-16"^^xsd:date and ?fecha&lt;="2015-02-17"^^xsd:date and ?estacion=&lt;http://www.zaragoza.es/api/recurso/medio-ambiente/calidad-aire/estacion/26&gt; and regex(?uri, "horaria"))
}
order by ?magnitud ?estacion ?fecha</pre>
<h4>Obtener contaminante, estacion, fecha,valor medicion diaria, y verficacion para una estacion y fecha concreta</h4>
<pre>
PREFIX ssn:&lt;http://purl.oclc.org/NET/ssnx/ssn#&gt;
PREFIX ssnext:&lt;http://vocab.linkeddata.es/datosabiertos/def/medio-ambiente/calidad-aire/ssn-ext#&gt;
PREFIX dul:&lt;http://www.loa-cnr.it/ontologies/DUL.owl#&gt;
select distinct ?uri ?magnitud ?estacion ?fecha ?valor ?verif
where {
        ?uri a ssn:Observation;
        ssn:observedBy ?estacion;
        ssn:observationResult ?res;
        ssn:observedProperty ?magnitud;
        ssnext:observationStatus ?verif;
        ssn:observationResultTime ?fecha.
        ?res ssn:hasValue/dul:hasDataValue ?valor
  filter  (?fecha>"2015-02-16"^^xsd:date and ?fecha&lt;="2015-02-17"^^xsd:date and ?estacion=&lt;http://www.zaragoza.es/api/recurso/medio-ambiente/calidad-aire/estacion/26&gt; and regex(?uri, "diaria"))
}
order by ?magnitud ?estacion ?fecha
</pre>
<h4>Obtener las propiedades de una estación</h4>
<pre xml:space="preserve">
PREFIX ssn:&lt;http://vocab.linkeddata.es/datosabiertos/def/medio-ambiente/meteorologia#&gt;
PREFIX esairq:&lt;http://vocab.linkeddata.es/datosabiertos/def/medio-ambiente/calidad-aire#&gt;
PREFIX loc:&lt;http://www.w3.org/ns/locn#&gt;
PREFIX geo:&lt;http://www.w3.org/2003/01/geo/wgs84_pos#&gt;
select distinct ?label ?distancia ?via ?trafico ?zona ?address ?geo
where {
        ?uri a ssn:Estacion;
        rdfs:label ?label;
esairq:distanciaObstaculos ?distancia;
esairq:distanciaVia ?via;
esairq:trafico ?trafico;
esairq:zona ?zona;
loc:address ?address;
geo:geometry ?geo
}  
</pre>

Se debe trabajar sobre el grafo http://www.zaragoza.es/medio-ambiente/nivel-polen/
<h4>Mostrar todas las observaciones existentes</h4>
<pre xml:space="preserve">PREFIX ssn:&lt;http://purl.oclc.org/NET/ssnx/ssn#&gt;
PREFIX ssnext:&lt;http://vocab.linkeddata.es/datosabiertos/def/medio-ambiente/calidad-aire/ssn-ext#&gt;
PREFIX dul:&lt;http://www.loa-cnr.it/ontologies/DUL.owl#&gt;
PREFIX time:&lt;http://www.w3.org/2006/time#&gt;
select distinct ?planta ?valor ?fecha str(?dia) as ?dia str(?mes) as ?mes ?year 
where{
        ?uri a ssn:Observation;
	ssn:observationResult ?res;
	ssn:observedProperty ?planta.
	?uri ssn:observationResultTime ?fecha.
	?fecha time:day ?dia. 
	?fecha time:month ?mes. 
	?fecha time:year ?year. 
	?res ssn:hasValue/dul:hasDataValue ?valor.
	}
	order by desc (?mes) desc (?dia)
</pre>

<h4>Mostrar todas las observaciones sobre las Moreras</h4>
<pre xml:space="preserve">
PREFIX ssn:&lt;http://purl.oclc.org/NET/ssnx/ssn#&gt;
PREFIX ssnext:&lt;http://vocab.linkeddata.es/datosabiertos/def/medio-ambiente/calidad-aire/ssn-ext#&gt;
PREFIX dul:&lt;http://www.loa-cnr.it/ontologies/DUL.owl#&gt;
PREFIX time:&lt;http://www.w3.org/2006/time#&gt;
select distinct ?planta ?valor ?fecha str(?dia) as ?dia str(?mes) as ?mes ?year 
where{
        ?uri a ssn:Observation;
	ssn:observationResult ?res;
	ssn:observedProperty ?planta.
	?uri ssn:observationResultTime ?fecha.
	?fecha time:day ?dia. 
	?fecha time:month ?mes. 
	?fecha time:year ?year. 
	?res ssn:hasValue/dul:hasDataValue ?valor.
         filter ( regex(?planta, "Morus"))
	}
	order by desc (?mes) desc (?dia)</pre>

<h4>Mostrar información de dbpedia sobre las cupresaceas</h4>
<pre xml:space="preserve">
prefix prov:	&lt;http://www.w3.org/ns/prov#&gt;
select distinct ?planta ?img ?nom ?label ?clase group_concat(distinct ?family;separator=\",\") as ?family ?genus ?king ?order ?phylum ?abstract group_concat(distinct ?external;separator=\",\") as ?external ?deri ?species ?tribus"
where {
optional{?planta dbpedia-owl:thumbnail ?img.} 
optional{?planta foaf:name ?nom.}
optional{?planta rdfs:label ?label.}
optional{?planta dbpedia-owl:class ?clase.} 
optional{?planta dbpedia-owl:family ?family.}
optional{?planta dbpedia-owl:kingdom ?king.}
optional{?planta dbpedia-owl:order ?order.} 
optional{?planta dbpedia-owl:abstract ?abstract.} 
optional{?planta dbpedia-owl:wikiPageExternalLink ?external.} 
optional{?planta prov:wasDerivedFrom ?deri.}
optional{?planta dbpedia-owl:phylum ?phylum.}
optional{?planta &lt;http://es.dbpedia.org/property/species&gt; ?species.}
optional{?planta &lt;http://es.dbpedia.org/property/tribus&gt; ?tribus.}
optional{?planta dbpedia-owl:genus ?genus.}
FILTER(?planta=&lt;http://es.dbpedia.org/resource/Cupressaceae&gt;)
}
</pre>

Las consultas se realizan sobre el punto <a href="http://www.zaragoza.es/ciudad/risp/sparql.htm">SPARQL</a> y el <strong>grafo: http://www.zaragoza.es/turismo/monumento/</strong><br/>
<h4>Monumentos destacados</h4>
<pre xml:space="preserve">PREFIX monumento: &lt;http://vocab.linkeddata.es/datosabiertos/def/turismo/lugar#&gt;

SELECT DISTINCT ?uri ?title 
WHERE { ?uri a monumento:LugarInteresTuristico. 
   OPTIONAL{ ?uri rdfs:label  ?title}.
   ?uri monumento:destacado "S".
}</pre>
<h4>Detalle del Monumento con id=32</h4>
<pre xml:space="preserve">SELECT distinct ?uri ?title ?latitud ?longitud ?modified ?tel ?fax ?comment ?foursquare ?datacion ?uso ?datosAcceso ?estilo ?puntosInteres ?streetAdr ?horario ?price ?detalleVisita ?photo 
WHERE { ?uri a &lt;http://vocab.linkeddata.es/datosabiertos/def/turismo/lugar#LugarInteresTuristico&gt;. 
OPTIONAL {?uri rdfs:label  ?title.}
OPTIONAL {?uri dcterms:modified  ?modified.}
OPTIONAL {?uri rdfs:comment  ?comment.}
OPTIONAL {?uri &lt;http://www.w3.org/2006/vcard/ns#photo&gt;  ?photo.}
OPTIONAL {?uri &lt;http://schema.org/streetAddress&gt;  ?streetAdr.}
OPTIONAL {?uri &lt;http://vocab.linkeddata.es/datosabiertos/def/turismo/lugar#estiloArtistico&gt;  ?estilo.}
OPTIONAL {?uri &lt;http://vocab.linkeddata.es/datosabiertos/def/turismo/lugar#puntosInteres&gt;  ?puntosInteres.}
OPTIONAL {?uri &lt;http://vocab.linkeddata.es/datosabiertos/def/turismo/lugar#datacion&gt;  ?datacion.}
OPTIONAL {?uri &lt;http://schema.org/price&gt;  ?price.}
OPTIONAL {?uri &lt;http://vocab.linkeddata.es/datosabiertos/def/turismo/lugar#uso&gt;  ?uso.}
OPTIONAL {?uri &lt;http://schema.org/openingHours&gt;  ?horario.}
OPTIONAL {?uri &lt;http://vocab.linkeddata.es/datosabiertos/def/turismo/lugar#foursquare&gt;  ?foursquare.}
OPTIONAL {?uri &lt;http://vocab.linkeddata.es/datosabiertos/def/turismo/lugar#datosAcceso&gt; ?datosAcceso.}
OPTIONAL {?uri &lt;http://vocab.linkeddata.es/datosabiertos/def/turismo/lugar#detalleVisita&gt; ?detalleVisita.}
OPTIONAL {?uri &lt;http://schema.org/telephone&gt; ?tel.}
OPTIONAL {?uri &lt;http://schema.org/faxNumber&gt; ?fax.}
OPTIONAL {?uri geo:geometry ?geo.
?geo geo:lat ?latitud.
?geo geo:long ?longitud}.
?uri dcterms:identifier "32".
}</pre>

Las consultas se realizan sobre el punto <a href="http://www.zaragoza.es/ciudad/risp/sparql.htm">SPARQL</a> y el <strong>grafo: http://www.zaragoza.es/sector-publico/organismo/</strong><br/>
<h4>Servicios que dependen de la dirección de ciencia y tecnología id=26009</h4>
<pre xml:space="preserve">PREFIX orgzar: &lt;http://vocab.linkeddata.es/kos/sector-publico/&gt; 
PREFIX w3org: &lt;http://www.w3.org/ns/org#&gt;
SELECT DISTINCT ?uri ?nombre ?superior WHERE {
        ?uri a orgzar:organismo. 
        ?uri rdfs:label ?nombre.
        ?uri w3org:unitOf ?superior
        FILTER(?superior='http://www.zaragoza.es/api/recurso/sector-publico/organismo/26009')
}</pre>
<h4>Depedencias ubicadas en en el edificio seminario (Vía hispanidad 20)</h4>
<pre xml:space="preserve">PREFIX orgzar: &lt;http://vocab.linkeddata.es/kos/sector-publico/&gt; 
PREFIX vcard: &lt;http://www.w3.org/2006/vcard/ns#&gt;
SELECT DISTINCT ?uri ?nombre ?address WHERE {
        ?uri a orgzar:organismo. 
        ?uri rdfs:label ?nombre.
        ?uri vcard:address ?addressInt.
                ?addressInt vcard:street-adr ?address.
        FILTER(?address="HISPANIDAD, VIA,20"^^xsd:string)
}</pre>
